Given a 2D matrix mat[][] of integers, find the maximum sum among all possible submatrices.Example:Input: mat[][] = [[1, 2, -1, -4, -20],                            [-8, -3, 4, 2, 1],                           [3, 8, 10, 1, 3],                          [-4, -1, 1, 7, -6]]Output: 29Explanation: The matrix is as follows and the green rectangle denotes the maximum sum rectangle which is equal to 29.Try It YourselfThis problem is mainly an extension of the Maximum Subarray Sum.Table of Content[Naive approach] - Iterating Over All Possible Submatrices - O((n*m)^3) time and O(1) space[Better Approach] - Using Prefix Sum - O((n*m)^2) time and O(n*m) space[Expected Approach] - Using Kadane’s Algorithm - O(n*m^2) time and  O(n) space[Naive approach] - Iterating Over All Possible Submatrices - O((n*m)3) time and O(1) spaceWe explore all possible rectangles in the given 2D array, by using four variables: two to define the left and right boundaries and two more to define the top and bottom boundaries and calculate their sums, and keep track of the maximum sum found.
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

//Driver Code Ends

int maxRectSum(vector<vector<int>> &mat) {

    int n = mat.size();
    int m = mat[0].size();
    int maxSum = INT_MIN;

    for (int up = 0; up < n; up++) {
        for (int left = 0; left < m; left++) {
            for (int down = up; down < n; down++) {
                for (int right = left; right < m; right++) {

                    // Find the sum of submatrix(up, right, down, left)
                    int sum = 0;
                    for (int i = up; i <= down; i++) {
                        for (int j = left; j <= right; j++) {
                            sum += mat[i][j];
                        }
                    }

                    // Update maxSum if sum > maxSum.
                    if (sum > maxSum) {
                        maxSum = sum;
                    }
                }
            }
        }
    }

    return maxSum;
}

//Driver Code Starts

int main() {
    vector<vector<int>> mat = {{1, 2, -1, -4, -20}, 
                               {-8, -3, 4, 2, 1}, 
                               {3, 8, 10, 1, 3}, 
                               {-4, -1, 1, 7, -6}};

    cout << maxRectSum(mat) << endl;
    return 0;
}
